using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class AmélieNothomb
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Grâce à l'ennemi, ce sinistre accident qu'est la vie devient une épopée.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "L'univers existe pour que j'existe.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Je comprenais que je ne pouvais me contenter de l'aimer : il fallait aussi qu'elle m'aimât.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "La neige, eau éclatée, sable de gel, sel non pas de la terre, mais du ciel, sel non salé, au goût de silex, à la texture de gemme pilée, au parfun de froidure, pigment du blanc, seule couleur qui tombre des nuages.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "La prétention fait écrire.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Qu'est-ce qu'une fleur ? Un sexe géant qui s'est mis sur son trente et un.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Les adultes ne peuvent pas faire plus beau cadeau aux enfants que de les oublier.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Je m'aperçois à l'instant qu'à l'adjectif lisse ne correspond aucun substantif. Pas étonnant : le vocabulaire du bonheur et du plaisir a toujours été le plus pauvre, et ce dans toutes les langues.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "J'ai toujours su que l'âge adulte ne comptait pas : dès la puberté, l'existence n'est plus qu'un épilogue.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Y a-t-il encore des esprits assez naïfs pour s'imaginer que les théories servent à être crues ? Les théories servent à irriter les philistins, à séduire les esthètes et à faire rire les autres.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "On se moque des enfants qui justifient leurs mauvais coups par ce gémissement : « C'est lui qui a commencé ! » Or, aucun conflit adulte ne trouve sa genèse ailleurs.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Affronter un bavard est une épreuve, certes. Mais que faire de celui qui vous envahit pour vous imposer son mutisme ?", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Il est bien plus divertissant d'être ennuyeux que d'être intéressant.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Comme l’or, le bien ne se rencontre jamais à l’état pur dans la nature : il est donc normal de ne pas le trouver impressionnant. Il a la fâcheuse habitude de ne rien faire ; il préfère se donner en spectacle.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Le bonheur forcé est un cauchemar.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Le cérémonial a toujours servi à se mettre du plomb dans la cervelle. Sans la grandiloquence des rites, on n'aurait de force pour rien.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Être malheureux en juin est aussi inconvenant que d'être heureux en écoutant du Schubert.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Gâchons notre vie dans l'espoir que cela gâche aussi la vie des autres", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "L'esprit a des systèmes de défense incompréhensible", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Quand on aime rien, il faut mourir", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Quand un obèse de soixante dix ans meurt dans son lit, personne ne se pose de question", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Les employés de Yumimoto, comme les zéros, ne prenaient leur valeur que derrière les autres chiffres. Tous, sauf moi, qui n'atteignais même pas le pouvoir de zéro.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Aussi longtemps qu'il existerait des fenêtres, le moindre humain de la terre aurait sa part de liberté.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Bien plus que les problèmes métaphysiques, ce sont les infimes contrariétés qui signalent l'absurdité de l'existence.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Je ne peux pas vous empêcher de parler ce n'est pas interdit. Vous ne pouvez pas me forcer à répondre ce n'est pas obligatoire.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Moi ce que j'aime dans la vie ce sont les nuisances autorisées. Elles sont d'autant plus amusantes que les victimes n'ont pas le droit de se défendre.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Vous savez, les adultes apprennent aux enfants à dire bonjour à la dame et à ne pas se mettre les doigts dans le nez. Ils ne leur apprennent pas à ne pas tuer leurs petits camarades de classe.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Rien n'est aussi puissant qu'un esprit animé par la foi. Qu'importe que Dieu existe ou non.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Sachez qu'il est très dur de découvrir la nullité de Dieu et, pour compenser, la toute puissance de l'ennemi intérieur. On croyait vivre avec un tyran bienveillant au-dessus de sa tête, on se rend compte qu'on vit sous la coupe d'un tyran malveillant qui est logé dans son ventre.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "L'être humain est une citadelle et […] les sens en sont les portes.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Croyez-vous que les gens malades de culpabilité aient besoin d'un motif sérieux ?", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Vous ne savez pas ce que c'est, d'avoir si soif et de ne pas avoir le droit de boire quand l'eau est sous vos yeux, belle, salvatrice, à portée de lèvres. L'eau se refuse, à vous qui venez de traverser la désert, pour ce motif incongru que vous n'êtes pas à son goût.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "On ne change pas le mode sans changer le sens.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "C'est flatteur, un viol. Ça prouve qu'on est capable de se mettre hors-la-loi pour vous.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Où va-t-on si on ne peut même plus assouvir ses pulsions dans des cimetières ?", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Cette fille, je la connaissais mieux que personne. Je l'avais violée, ce qui n'est déjà pas mal, je l'avais assassinée, ce qui reste la meilleure méthode pour découvrir intimement quelqu'un.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "On a déjà tant à aimer quand on ne sait de l'aimée que son prénom.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Appeler la police. La vengeance par procuration !", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "On ne peut pardonner que quand on est l'offensé.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Qu'est-ce qui coule dans vos veines ? De la tisane ?", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Pour convaincre un élu de sa mission, il faut en passer par ses nerfs.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Le coupable va vers son châtiment comme l'eau vers la mer, comme l'offensé vers sa vengeance.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Aucune loi n'interdit les fantasmes.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Le verbe refouler, c'est le mot fourre-tout du XXe siècle.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Tout ce qui grandit accroît sa capacité d'autodémolition.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Chacun tue ce qu'il aime. […] L'amour […] mène tout à sa perte.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "On ne peut risquer que sa vie. Et si on ne la risque pas, on ne vit pas.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "C'est drôle, ce besoin qu'ont les gens d'accuser les autres d'avoir gâché leur existence. Alors qu'ils y parviennent si bien eux-mêmes, sans l'aide de quiconque.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "À six ans, se déshabiller n’est rien. À vingt-six ans, se déshabiller est déjà une vieille habitude.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "À seize ans, se déshabiller est un acte d’une violence insensée.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Je me rappelais les discours des professeurs, « analysez le style de cet écrivain », « ce poème est très bien écrit, par exemple la voyelle unetelle apparaît quatre fois dans ce vers », etc. Ces dissections sont aussi lassantes qu'un amoureux détaillant à des tiers les charmes de sa bien-aimée. Ce n'est pas que la beauté littéraire n'existe pas : seulement, c'est une expérience aussi incommunicable que les grâces de la dulcinée pour qui n'y est pas sensible. Il faut s'éprendre soi-même ou se résoudre à ne jamais comprendre.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Et s'ils ont défailli à ce soutien en temps opportun, ne seraient-ils pas plus utiles à leur texte en l'aimant quand même, de cet amour véritable qui ne s'exprime pas par la logorrhée mais par un silence ponctué de mots forts ?", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "«Tu ne m'as rien donné et je souffre ! Je t'ai sauvée et tu me laisses crever de faim ! Et j'aurai faim jusqu'à ma mort ! Et tu trouves ça juste !»", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "On n'est jamais si heureux que quand on a trouvé le moyen de se perdre.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Tu as rendu quelqu'un heureux en étant claire. Il faut oser dire non. Il n'y a rien de gentil à laisser de faux espoirs. L'ambiguïté est la source de la douleur, etc.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Ceux qui s'évadent meurent perdus dans un excès d'espace. C'est le paradoxe de l'infini : on pressent une liberté qui n'y existe pas. C'est une prison si grande qu'on n'en sort jamais.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Or la liberté ne peut s'embarrasser de suspicion. Celui qui a décidé d'être libre ne peut avoir de ces pensées mesquines, tatillonnes, comptables, pourquoi a-t-il dit ça et non ceci, etc. Je voulais vivre à grandes enjambées, m'exalter d'exister.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "La mort n'est pas une disparition.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "La cuisine est un art et un pouvoir : il est hors de question que je me soumette à celui de qui que ce soit.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "La colocataire est la femme idéale.", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Récemment, un best-seller mondial a prétendu qu'il y avait des vampires gentils et innocents. Les gens ne sont jamais aussi contents, désormais, que quand on leur affirme que le mal n'existe pas. Mais non, les méchants ne sont pas de vrais méchants, le bien les séduit, eux aussi. Quelle espèce de crétins abâtardis sommes-nous devenus pour gober et aimer ces théories à la noix ?", Author = "Amélie Nothomb" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Amélie_Nothomb", Text = "Dans le roman, ô merveille, tout est permis. On peut tuer.", Author = "Amélie Nothomb" },
        };
    }
}